void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalize screen coordinates
    vec2 uv = (fragCoord.xy - iResolution.xy * 0.5) / iResolution.y;

    // Time-based grid warping
    vec2 moire = vec2(sin(uv.x * 10.0 + iTime * 1.5), cos(uv.y * 10.0 - iTime * 0.5));

    // Recursive fractal grid distortion
    float fractal = 0.0;
    for(int i = 1; i < 40; i++) {
        fractal += 0.2 * sin(moire.x * 8.0 + iTime * 0.7 + float(i) * 0.1);
    }

    // Psychedelic color shifting
    vec3 color = vec3(0.0);
    color += vec3(1.0, 0.5, 0.0) * sin(moire.y * 20.0 + fractal);
    color += vec3(0.0, 1.0, 0.5) * cos(moire.x * 30.0 + fractal);
    color += vec3(0.5, 0.0, 1.0) * sin(moire.y * 40.0 + fractal);

    // Output final color
    fragColor = vec4(color, 1.0);
}
